import{_ as i,l,o as a,c as s,v as t,p as d,x as r,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"行级安全","description":"","frontmatter":{"title":"行级安全","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/row-level-security.md","filePath":"cs/row-level-security.md","lastUpdated":1789023840000}'),S={name:"cs/row-level-security.md"};function _(h,e,E,u,T,A){const o=l("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="行级安全" tabindex="-1">行级安全 <a class="header-anchor" href="#行级安全" aria-label="Permalink to &quot;行级安全&quot;">​</a></h1><div class="epigraph"><p>视图和授权若只到表，租户仍能看见别人的行。行级策略把谓词接到扫描上，使「当前用户」成为计划的一部分。</p><footer>—— 据 PostgreSQL RLS；关系系统安全视图传统</footer></div><p><a href="/cs/jepsen-testing">上一课</a>查隔离是否撒谎。缺口是<strong>谁被允许看见哪一行</strong>：隔离正确仍可能越权。本课钉行级安全；审计下一课记谁读过。不把 RLS 写成密码学。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>GRANT SELECT ON t</code> 太粗。RLS：对表附策略，<code>USING</code> 谓词在查询里合取。缺口是计划：策略必须稳定、可下推，否则每行调函数会打爆 OLTP。超级用户绕过、BYPASSRLS、安全定义者函数是常见洞。多租户用 <code>tenant_id = current_setting(...)</code> 必须防会话被改。</p><p><span class="marginnote">强制访问与自主访问不同。RLS 默认是自主的、可绕过的，除非角色设计把绕过封死。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>策略尽量用列与会话变量，避免每行查外表。测试：同一 SQL 换角色看行数。与视图：视图可漏 WITH CHECK。与审计：绕过事件也要记。与 TPC：基准角色通常是全能用户，测不出 RLS。</p>',8)),(a(),d(p,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20P%5B%22%E7%AD%96%E7%95%A5%E8%B0%93%E8%AF%8D%22%5D%0A%20%20P%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%20%2F%20%E7%B4%A2%E5%BC%95%22%5D%0A%20%20ROLE%5B%22%E8%A7%92%E8%89%B2%22%5D%20--%3E%20P%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>策略是查询改写：计划里多一个滤子。索引能否服务该滤子决定 OLTP 能否活。漏 WITH CHECK 会让 <code>INSERT</code> 写进自己看不见的行。计划缓存必须按角色分键，否则串计划泄密或用管理员统计估错租户选择率。CDC 与复制槽通常绕过 RLS，权限要单开。向量/搜索侧过滤必须在 ANN 前或保证租户隔离，否则跨租户召回。</p><p>超级用户、BYPASSRLS、SECURITY DEFINER 函数是绕过面。物化视图与 FDW 也可能漏策略。会话变量若可被租户 <code>SET</code>，策略等于没有。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不设计某云产品的 IAM。下一课审计是责任链，RLS 是强制滤子。不要靠 RLS 替代加密或 TDE。TPC 基准角色通常全能，测不出策略。</p><p>后课默认：多租户用强制行谓词且可下推。应用层 WHERE 不是 RLS——有基表权限就会绕过。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RLS 把授权谓词合进扫描；计划与绕过路径是漏洞面。</li><li>会话变量必须不可被租户改写；缓存按角色隔离。</li><li>数据库审计下一课。</li><li>出处：PostgreSQL RLS；安全视图传统。</li></ul>',8))])}const L=i(S,[["render",_]]);export{P as __pageData,L as default};
